int32_t MAX_BERNOULLI = 62;

/**
* Computes the nth Bernoulli number of a single-precision floating-point number.
*
* @param n    input value
* @return     output value
*
* @example
* float out = stdlib_base_bernoullif( 0 );
* // returns 1
*/
float stdlib_base_bernoullif( const int32_t n ) {
	if ( stdlib_base_is_nanf( n ) || !stdlib_base_is_nonnegative_integer( n ) ) {
		return 0.0 / 0.0; // NaN
	}
	if ( stdlib_base_is_odd( n ) ) {
		return 0.0;
	}
	if ( n > MAX_BERNOULLI ) {
		return ( ( n / 2 ) & 1 ) ? STDLIB_CONSTANT_FLOAT32_PINF : STDLIB_CONSTANT_FLOAT32_NINF;
	}
	return bernoulli_value[ n / 2 ];
}
